import { sqliteTable, text, integer, primaryKey, index, uniqueIndex } from 'drizzle-orm/sqlite-core';

// Generated by Better Auth. Run `pnpm run auth:generate` to update these
// tables instead of editing them directly, such as after adding an auth plugin.

export const user = sqliteTable('user', {
  id: text('id').primaryKey(),
  name: text('name').notNull(),
  email: text('email').notNull().unique(),
  emailVerified: integer('email_verified', { mode: 'boolean' })
    .notNull()
    .default(false),
  image: text('image'),
  createdAt: integer('created_at', { mode: 'timestamp' })
    .notNull()
    .$defaultFn(() => new Date()),
  updatedAt: integer('updated_at', { mode: 'timestamp' })
    .notNull()
    .$defaultFn(() => new Date()),
  role: text('role'),
  banned: integer('banned', { mode: 'boolean' }).default(false),
  banReason: text('ban_reason'),
  banExpires: integer('ban_expires', { mode: 'timestamp' })
});

export const session = sqliteTable('session', {
  id: text('id').primaryKey(),
  expiresAt: integer('expires_at', { mode: 'timestamp' }).notNull(),
  token: text('token').notNull().unique(),
  createdAt: integer('created_at', { mode: 'timestamp' }).notNull(),
  updatedAt: integer('updated_at', { mode: 'timestamp' }).notNull(),
  ipAddress: text('ip_address'),
  userAgent: text('user_agent'),
  userId: text('user_id')
    .notNull()
    .references(() => user.id, { onDelete: 'cascade' }),
  impersonatedBy: text('impersonated_by')
});

export const account = sqliteTable('account', {
  id: text('id').primaryKey(),
  accountId: text('account_id').notNull(),
  providerId: text('provider_id').notNull(),
  userId: text('user_id')
    .notNull()
    .references(() => user.id, { onDelete: 'cascade' }),
  accessToken: text('access_token'),
  refreshToken: text('refresh_token'),
  idToken: text('id_token'),
  accessTokenExpiresAt: integer('access_token_expires_at', {
    mode: 'timestamp'
  }),
  refreshTokenExpiresAt: integer('refresh_token_expires_at', {
    mode: 'timestamp'
  }),
  scope: text('scope'),
  password: text('password'),
  createdAt: integer('created_at', { mode: 'timestamp' }).notNull(),
  updatedAt: integer('updated_at', { mode: 'timestamp' }).notNull()
});

export const verification = sqliteTable('verification', {
  id: text('id').primaryKey(),
  identifier: text('identifier').notNull(),
  value: text('value').notNull(),
  expiresAt: integer('expires_at', { mode: 'timestamp' }).notNull(),
  createdAt: integer('created_at', { mode: 'timestamp' }).$defaultFn(
    () => new Date()
  ),
  updatedAt: integer('updated_at', { mode: 'timestamp' }).$defaultFn(
    () => new Date()
  )
});

// A project is one customer's product: it gets its own public board and roadmap.
export const projects = sqliteTable('project', {
  id: text('id').primaryKey(),
  slug: text('slug').notNull().unique(),
  name: text('name').notNull(),
  description: text('description').notNull().default(''),
  // An image URL. Uploads aren't supported, so the image is hosted elsewhere.
  avatarUrl: text('avatar_url').notNull().default(''),
  createdAt: integer('created_at').notNull(),
});

// People who manage a project from the dashboard. Everyone else is a visitor
// of its public board.
export const projectMembers = sqliteTable('project_member', {
  projectId: text('project_id').notNull().references(() => projects.id, { onDelete: 'cascade' }),
  userId: text('user_id').notNull().references(() => user.id, { onDelete: 'cascade' }),
  role: text('role', { enum: ['owner', 'admin'] }).notNull(),
  createdAt: integer('created_at').notNull(),
}, (table) => [primaryKey({ columns: [table.projectId, table.userId] }), index('member_user_idx').on(table.userId)]);

export const feedback = sqliteTable('feedback', {
  id: text('id').primaryKey(),
  // Nullable only because SQLite can't add a required column to a table that
  // already has rows. Every write sets it.
  projectId: text('project_id').references(() => projects.id, { onDelete: 'cascade' }),
  title: text('title').notNull(),
  description: text('description').notNull(),
  authorId: text('author_id').notNull().references(() => user.id),
  status: text('status', { enum: ['open', 'planned', 'in_progress', 'completed', 'closed'] }).notNull().default('open'),
  hidden: integer('hidden', { mode: 'boolean' }).notNull().default(false),
  mergedIntoId: text('merged_into_id'),
  createdAt: integer('created_at').notNull(),
  updatedAt: integer('updated_at').notNull(),
}, (table) => [index('feedback_project_idx').on(table.projectId), index('feedback_status_idx').on(table.status), index('feedback_author_idx').on(table.authorId)]);

// Categories belong to one project, so names only need to be unique within it.
export const tags = sqliteTable('feedback_category', {
  id: text('id').primaryKey(),
  projectId: text('project_id').notNull().references(() => projects.id, { onDelete: 'cascade' }),
  name: text('name').notNull(),
  color: text('color').notNull().default('blue'),
}, (table) => [uniqueIndex('category_project_name_idx').on(table.projectId, table.name)]);

export const feedbackTags = sqliteTable('feedback_tags', {
  postId: text('post_id').notNull().references(() => feedback.id, { onDelete: 'cascade' }),
  tagId: text('tag_id').notNull().references(() => tags.id, { onDelete: 'cascade' }),
}, (table) => [primaryKey({ columns: [table.postId, table.tagId] })]);

export const votes = sqliteTable('feedback_vote', {
  postId: text('post_id').notNull().references(() => feedback.id, { onDelete: 'cascade' }),
  userId: text('user_id').notNull().references(() => user.id, { onDelete: 'cascade' }),
  createdAt: integer('created_at').notNull(),
}, (table) => [primaryKey({ columns: [table.postId, table.userId] })]);

export const comments = sqliteTable('feedback_comment', {
  id: text('id').primaryKey(),
  postId: text('post_id').notNull().references(() => feedback.id, { onDelete: 'cascade' }),
  authorId: text('author_id').notNull().references(() => user.id),
  body: text('body').notNull(),
  hidden: integer('hidden', { mode: 'boolean' }).notNull().default(false),
  createdAt: integer('created_at').notNull(),
}, (table) => [index('comment_post_idx').on(table.postId)]);

export const statusUpdates = sqliteTable('feedback_update', {
  id: text('id').primaryKey(),
  postId: text('post_id').notNull().references(() => feedback.id, { onDelete: 'cascade' }),
  authorId: text('author_id').notNull().references(() => user.id),
  status: text('status').notNull(),
  message: text('message').notNull(),
  createdAt: integer('created_at').notNull(),
});

export const wishboxMeta = sqliteTable('wishbox_meta', {
  key: text('key').primaryKey(),
  value: text('value').notNull(),
});
